from __future__ import annotations

import ast
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "pedolgov"

FORBIDDEN = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "comprehensive",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "meticulously",
    "it's worth noting",
    "in conclusion",
    "state-of-the-art",
)
PRIVATE = ("/users/", "miniconda", "homebrew", "/desktop/code", "chenzhenghan")


def _package_files() -> list[Path]:
    return sorted(PACKAGE.rglob("*.py"))


def test_no_comments_in_package() -> None:
    for path in _package_files():
        with path.open("rb") as handle:
            for tok in tokenize.tokenize(handle.readline):
                assert tok.type != tokenize.COMMENT, f"comment in {path}"


def test_no_docstrings_in_package() -> None:
    for path in _package_files():
        tree = ast.parse(path.read_text(encoding="utf-8"))
        nodes = [
            tree,
            *[
                n
                for n in ast.walk(tree)
                if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
            ],
        ]
        for node in nodes:
            assert ast.get_docstring(node) is None, f"docstring in {path}"


def _text_files() -> list[Path]:
    files: list[Path] = []
    for pattern in ("pedolgov/**/*.py", "tests/**/*.py", "docs/*.md", "configs/**/*.yaml"):
        files.extend(ROOT.glob(pattern))
    readme = ROOT / "README.md"
    if readme.exists():
        files.append(readme)
    return [f for f in files if f.name != "test_style_guard.py"]


def test_no_forbidden_phrases() -> None:
    for path in _text_files():
        lowered = path.read_text(encoding="utf-8").lower()
        for phrase in FORBIDDEN:
            assert phrase not in lowered, f"forbidden phrase {phrase!r} in {path.name}"


def test_no_private_strings() -> None:
    for path in _text_files():
        lowered = path.read_text(encoding="utf-8").lower()
        for token in PRIVATE:
            assert token not in lowered, f"private string {token!r} in {path.name}"


def test_no_emoji() -> None:
    for path in _text_files():
        for ch in path.read_text(encoding="utf-8"):
            code = ord(ch)
            assert not (0x1F000 <= code <= 0x1FAFF), f"emoji in {path.name}"
            assert not (0x2600 <= code <= 0x27BF), f"emoji in {path.name}"


def test_readme_omits_code_availability_and_citation() -> None:
    readme = (ROOT / "README.md").read_text(encoding="utf-8").lower()
    assert "code availability" not in readme
    assert "\ncitation" not in readme and "# citation" not in readme


def test_project_context_neutral_title() -> None:
    ctx = (ROOT / "docs" / "project-context.md").read_text(encoding="utf-8").lower()
    assert "auto-derived" not in ctx
    assert "auto-driven" not in ctx
